PRAGMA defer_foreign_keys=ON;
CREATE TABLE family_communication_information(
 id TEXT PRIMARY KEY,store_id TEXT NOT NULL REFERENCES stores(id),customer_id TEXT NOT NULL REFERENCES customers(id),recipient_id TEXT NOT NULL REFERENCES users(id),kind TEXT NOT NULL CHECK(kind IN('notification','consent')),revision INTEGER NOT NULL CHECK(revision>0),sequence INTEGER NOT NULL CHECK(sequence>0),action TEXT NOT NULL CHECK(action IN('publish','withdraw')),public_note TEXT NOT NULL,internal_reason TEXT NOT NULL,created_at TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),UNIQUE(customer_id,recipient_id,kind,revision),UNIQUE(store_id,sequence));
CREATE VIEW family_communication_information_current AS SELECT i.* FROM family_communication_information i WHERE revision=(SELECT max(revision) FROM family_communication_information WHERE customer_id=i.customer_id AND recipient_id=i.recipient_id AND kind=i.kind);
CREATE TABLE family_communication_actions(
 id TEXT PRIMARY KEY,root_id TEXT NOT NULL REFERENCES family_communication_actions(id) DEFERRABLE INITIALLY DEFERRED,information_id TEXT NOT NULL REFERENCES family_communication_information(id),information_sequence INTEGER NOT NULL CHECK(information_sequence>0),store_id TEXT NOT NULL REFERENCES stores(id),customer_id TEXT NOT NULL REFERENCES customers(id),recipient_id TEXT NOT NULL REFERENCES users(id),kind TEXT NOT NULL CHECK(kind IN('preference','consent_adjustment')),revision INTEGER NOT NULL CHECK(revision>0),sequence INTEGER NOT NULL CHECK(sequence>0),action TEXT NOT NULL CHECK(action IN('submit','review','withdraw')),channel TEXT CHECK(channel IN('in_app','phone','sms','email','wechat','none','unknown')),notification_choice TEXT CHECK(notification_choice IN('yes','no','unknown')),public_note TEXT NOT NULL,internal_reason TEXT,created_at TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),UNIQUE(root_id,revision),UNIQUE(store_id,sequence),CHECK(kind='preference' AND channel IS NOT NULL AND notification_choice IS NOT NULL OR kind='consent_adjustment' AND channel IS NULL AND notification_choice IS NULL));
CREATE VIEW family_communication_action_current AS SELECT e.* FROM family_communication_actions e WHERE revision=(SELECT max(revision) FROM family_communication_actions WHERE root_id=e.root_id);
CREATE TRIGGER family_communication_information_source BEFORE INSERT ON family_communication_information BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM customers WHERE id=NEW.customer_id AND store_id=NEW.store_id AND created_at<=NEW.created_at) OR NEW.revision<>coalesce((SELECT max(revision)+1 FROM family_communication_information WHERE customer_id=NEW.customer_id AND recipient_id=NEW.recipient_id AND kind=NEW.kind),1) OR NEW.sequence<>coalesce((SELECT max(sequence)+1 FROM family_communication_information WHERE store_id=NEW.store_id),1) OR NEW.action='withdraw' AND NOT EXISTS(SELECT 1 FROM family_communication_information_current WHERE customer_id=NEW.customer_id AND recipient_id=NEW.recipient_id AND kind=NEW.kind AND action='publish') THEN RAISE(ABORT,'family communication fixed current information') END;
END;
CREATE TRIGGER family_communication_action_source BEFORE INSERT ON family_communication_actions BEGIN
 SELECT CASE WHEN NEW.information_sequence<>coalesce((SELECT max(sequence) FROM family_communication_information WHERE store_id=NEW.store_id),0) OR NEW.sequence<>coalesce((SELECT max(sequence)+1 FROM family_communication_actions WHERE store_id=NEW.store_id),1) OR NOT EXISTS(SELECT 1 FROM family_communication_information i WHERE i.id=NEW.information_id AND i.store_id=NEW.store_id AND i.customer_id=NEW.customer_id AND i.recipient_id=NEW.recipient_id AND i.action='publish' AND i.kind=CASE NEW.kind WHEN 'preference' THEN 'notification' ELSE 'consent' END) OR NEW.action='submit' AND (NEW.id<>NEW.root_id OR NEW.revision<>1 OR NEW.internal_reason IS NOT NULL OR NOT EXISTS(SELECT 1 FROM family_communication_information_current i WHERE i.id=NEW.information_id AND i.action='publish')) OR NEW.action<>'submit' AND NOT EXISTS(SELECT 1 FROM family_communication_action_current c JOIN family_communication_actions r ON r.id=c.root_id WHERE c.root_id=NEW.root_id AND c.action<>'withdraw' AND NEW.revision=c.revision+1 AND r.information_id=NEW.information_id AND r.store_id=NEW.store_id AND r.customer_id=NEW.customer_id AND r.recipient_id=NEW.recipient_id AND r.kind=NEW.kind AND r.channel IS NEW.channel AND r.notification_choice IS NEW.notification_choice) OR EXISTS(SELECT 1 FROM family_communication_information w JOIN family_communication_information i ON i.id=NEW.information_id WHERE w.customer_id=i.customer_id AND w.recipient_id=i.recipient_id AND w.kind=i.kind AND w.action='withdraw' AND w.revision>=i.revision) THEN RAISE(ABORT,'family communication original explicit action') END;
END;
CREATE TRIGGER family_communication_information_actor BEFORE INSERT ON family_communication_information BEGIN
 SELECT CASE WHEN (1) AND (NEW.internal_reason IS NULL OR NOT EXISTS(SELECT 1 FROM users u LEFT JOIN user_security s ON s.user_id=u.id WHERE u.id=NEW.created_by AND u.store_id=NEW.store_id AND u.active=1 AND u.role IN('manager','reception') AND coalesce(s.must_change_password,0)=0)) OR (NEW.action='publish') AND NOT EXISTS(SELECT 1 FROM users u JOIN guardian_links g ON g.user_id=u.id LEFT JOIN user_security s ON s.user_id=u.id WHERE u.id=NEW.recipient_id AND g.customer_id=NEW.customer_id AND g.active=1 AND u.role='guardian' AND u.active=1 AND coalesce(s.must_change_password,0)=0) THEN RAISE(ABORT,'family communication current actor/authorization') END;END;
CREATE TRIGGER family_communication_information_text BEFORE INSERT ON family_communication_information WHEN length(trim(NEW.public_note)) NOT BETWEEN 1 AND 2000 OR length(NEW.public_note)>2000 OR instr(NEW.public_note,char(0))>0 OR NEW.internal_reason IS NOT NULL AND (length(trim(NEW.internal_reason)) NOT BETWEEN 1 AND 300 OR length(NEW.internal_reason)>300 OR instr(NEW.internal_reason,char(0))>0) BEGIN SELECT RAISE(ABORT,'family communication separate public/internal text');END;
CREATE TRIGGER family_communication_information_time BEFORE INSERT ON family_communication_information WHEN length(NEW.created_at)<>24 OR strftime('%Y-%m-%dT%H:%M:%fZ',NEW.created_at) IS NOT NEW.created_at OR EXISTS(SELECT 1 FROM family_communication_information WHERE store_id=NEW.store_id AND created_at>NEW.created_at) BEGIN SELECT RAISE(ABORT,'family communication canonical saved time');END;
CREATE TRIGGER family_communication_information_no_update BEFORE UPDATE ON family_communication_information BEGIN SELECT RAISE(ABORT,'family communication immutable');END;
CREATE TRIGGER family_communication_information_no_delete BEFORE DELETE ON family_communication_information BEGIN SELECT RAISE(ABORT,'family communication immutable');END;
CREATE TRIGGER family_communication_actions_actor BEFORE INSERT ON family_communication_actions BEGIN
 SELECT CASE WHEN (NEW.action='review') AND (NEW.internal_reason IS NULL OR NOT EXISTS(SELECT 1 FROM users u LEFT JOIN user_security s ON s.user_id=u.id WHERE u.id=NEW.created_by AND u.store_id=NEW.store_id AND u.active=1 AND u.role IN('manager','reception') AND coalesce(s.must_change_password,0)=0)) OR (NEW.action IN('submit','withdraw') OR NEW.action='review') AND NOT EXISTS(SELECT 1 FROM users u JOIN guardian_links g ON g.user_id=u.id LEFT JOIN user_security s ON s.user_id=u.id WHERE u.id=NEW.recipient_id AND g.customer_id=NEW.customer_id AND g.active=1 AND u.role='guardian' AND u.active=1 AND coalesce(s.must_change_password,0)=0) OR NEW.action IN('submit','withdraw') AND (NEW.created_by<>NEW.recipient_id OR NEW.internal_reason IS NOT NULL) THEN RAISE(ABORT,'family communication current actor/authorization') END;END;
CREATE TRIGGER family_communication_actions_text BEFORE INSERT ON family_communication_actions WHEN length(trim(NEW.public_note)) NOT BETWEEN 1 AND 2000 OR length(NEW.public_note)>2000 OR instr(NEW.public_note,char(0))>0 OR NEW.internal_reason IS NOT NULL AND (length(trim(NEW.internal_reason)) NOT BETWEEN 1 AND 300 OR length(NEW.internal_reason)>300 OR instr(NEW.internal_reason,char(0))>0) BEGIN SELECT RAISE(ABORT,'family communication separate public/internal text');END;
CREATE TRIGGER family_communication_actions_time BEFORE INSERT ON family_communication_actions WHEN length(NEW.created_at)<>24 OR strftime('%Y-%m-%dT%H:%M:%fZ',NEW.created_at) IS NOT NEW.created_at OR EXISTS(SELECT 1 FROM family_communication_actions WHERE store_id=NEW.store_id AND created_at>NEW.created_at) BEGIN SELECT RAISE(ABORT,'family communication canonical saved time');END;
CREATE TRIGGER family_communication_actions_no_update BEFORE UPDATE ON family_communication_actions BEGIN SELECT RAISE(ABORT,'family communication immutable');END;
CREATE TRIGGER family_communication_actions_no_delete BEFORE DELETE ON family_communication_actions BEGIN SELECT RAISE(ABORT,'family communication immutable');END;
